<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import Prism from 'prismjs';import 'prismjs/components/prism-javascript';import {harnessApi} from '../runtime-client/api';import type {Diagnostic,VersionDescriptor} from '../types';const props=defineProps<{appKey:string;versionId:number;compareVersionId?:number}>();const version=ref<VersionDescriptor>();const source=ref('');const compare=ref('');const diagnostics=ref<Diagnostic[]>([]);const status=ref('');const highlighted=computed(()=>Prism.highlight(source.value,Prism.languages.javascript,'javascript'));const diff=computed(()=>{const a=compare.value.split('\n'),b=source.value.split('\n'),n=Math.max(a.length,b.length);return Array.from({length:n},(_,i)=>({line:i+1,before:a[i]??'',after:b[i]??'',changed:a[i]!==b[i]})).filter(x=>x.changed)});const load=async()=>{version.value=await harnessApi.getVersion(props.appKey,props.versionId);source.value=version.value.source;if(props.compareVersionId)compare.value=(await harnessApi.getVersion(props.appKey,props.compareVersionId)).source};const save=async()=>{version.value=await harnessApi.saveSource(props.appKey,props.versionId,source.value);status.value='Draft saved'};const validate=async()=>{const r:any=await harnessApi.validate(props.appKey,props.versionId);diagnostics.value=r.diagnostics||[];status.value=r.valid?'Validation passed':'Validation failed';await load()};const publish=async()=>{await harnessApi.publish(props.appKey,props.versionId);status.value='Published';await load()};onMounted(load);</script>
<template><main class="harness-admin"><header><h1>Script v{{version?.versionNo}}</h1><span class="badge">{{version?.status}}</span></header><div class="editor-grid"><textarea v-model="source" class="script-input" spellcheck="false" :readonly="version?.status==='PUBLISHED'||version?.status==='SUPERSEDED'"/><pre class="script-highlight"><code class="language-javascript" v-html="highlighted"/></pre></div><div class="toolbar"><button @click="save" :disabled="version?.status==='PUBLISHED'||version?.status==='SUPERSEDED'">Save draft</button><button @click="validate" :disabled="version?.status==='PUBLISHED'||version?.status==='SUPERSEDED'">Validate</button><button @click="publish" :disabled="version?.status!=='VALIDATED'">Publish</button><span role="status">{{status}}</span></div><ul v-if="diagnostics.length" class="diagnostics"><li v-for="(d,i) in diagnostics" :key="i"><code>{{d.code}}</code> {{d.message}} <span v-if="d.line">({{d.line}}:{{d.column}})</span></li></ul><section v-if="compareVersionId"><h2>Source diff</h2><table><tr v-for="d in diff" :key="d.line"><th>{{d.line}}</th><td class="removed">{{d.before}}</td><td class="added">{{d.after}}</td></tr></table></section></main></template>
